import type { Meta, StoryObj } from "@storybook/react-vite";
import native from "../../../native/tokens.json";
import { Code, Page, Section } from "../tokens/token-docs";
import { Rule, Rules } from "./foundation-docs";

// Avenue on the phone apps (AVE-101). Neighbors and Management each ship a SwiftUI and a Jetpack Compose app.
// ui-sdk is web only, so those apps can't run Avenue's components: they take Avenue's tokens (native/, generated by
// `bun run tokens:native`) and build each screen from the platform's own control, styled with those tokens.

/** Each Avenue component and the control a phone app builds it from. */
const controls = [
  ["Button", "Button with a custom ButtonStyle", "Button, OutlinedButton, TextButton"],
  ["Toggle, Toolbar button", "Toggle with .button style", "IconToggleButton"],
  ["Toggle group", "Picker with .segmented style", "SingleChoiceSegmentedButtonRow"],
  ["Checkbox", "Toggle (iOS has no checkbox); a checkmark in list rows", "Checkbox"],
  ["Switch", "Toggle", "Switch"],
  ["Radio group", "Picker with .inline style, or a list with a checkmark", "RadioButton rows with selectableGroup"],
  ["Input, Search input", "TextField; .searchable for search", "OutlinedTextField; SearchBar"],
  ["Textarea", "TextField(axis: .vertical)", "OutlinedTextField with minLines"],
  ["Field", "A Form section with its label and footer", "supportingText and isError on the text field"],
  ["Select", "Picker with .menu style", "ExposedDropdownMenuBox"],
  ["Combobox", "A searchable list in a sheet", "ExposedDropdownMenuBox with a text field that filters"],
  ["Dialog, Form dialog", ".sheet", "ModalBottomSheet, or a full-screen dialog for long forms"],
  ["Alert dialog", ".alert or .confirmationDialog", "AlertDialog"],
  ["Sheet", ".sheet with presentationDetents", "ModalBottomSheet"],
  ["Dropdown menu", "Menu", "DropdownMenu"],
  ["Popover, Hover card", ".popover (a sheet on iPhone); phones have no hover", "A sheet or a tap-to-open panel"],
  ["Tooltip", "Nothing: put the words in the label", "PlainTooltip on long press, only for icon buttons"],
  ["Toast", "An overlay banner (iOS has no system toast)", "Snackbar"],
  ["Nav tab", "TabView", "NavigationBar"],
  ["Avatar, Initials avatar", "A circle with initials on a tint", "A circle with initials on a tint"],
  ["Badge, Status, Chip", "A capsule label with a status pair", "AssistChip, FilterChip; a capsule for status"],
  ["Card, Section card", "A grouped List section", "Card"],
  ["Table, Register", "List rows (no wide table on a phone)", "LazyColumn rows"],
  ["Disclosure", "DisclosureGroup", "An expandable row"],
  ["Empty state", "ContentUnavailableView", "A centred column: icon, title, action"],
  ["Inline message", "A row tinted with a status pair", "A row tinted with a status pair"],
  ["Money", "Text with .monospacedDigit()", "Text with tabular figures (fontFeatureSettings \"tnum\")"],
  ["File field", ".fileImporter or PhotosPicker", "ActivityResultContracts.GetContent"],
] as const;

const camel = (name: string) => name.replace(/-(\w)/g, (_, c: string) => c.toUpperCase());
const roles = Object.keys(native.light) as (keyof typeof native.light)[];

function Swatch({ hex }: { hex: string }) {
  return (
    <span className="inline-flex flex-wrap items-center gap-group">
      <span aria-hidden className="size-5 shrink-0 rounded-sm border" style={{ background: hex }} />
      <Code className="text-foreground">{hex}</Code>
    </span>
  );
}

function NativeUse() {
  return (
    <Page title="Native apps">
      <Section
        title="What the phone apps share"
        note="The iPhone and Android apps share Avenue's look, not its components. Avenue generates its colours, type scale, corners, spacing and tap size for them from the same stylesheets the web reads, with the web's names."
      >
        <Rules>
          <Rule why="ui-sdk renders in web frameworks only. A phone app built from SwiftUI or Compose gets the platform's keyboard, VoiceOver and TalkBack behaviour for free.">
            Build each screen from the platform's own control, and style it with Avenue's tokens.
          </Rule>
          <Rule
            why={
              <>
                Run <Code>bun run tokens:native</Code> after changing a token; the script tests fail until the files
                match.
              </>
            }
          >
            Copy <Code>native/AvenueTokens.swift</Code> or <Code>native/AvenueTokens.kt</Code> into the app. Never edit
            a value by hand.
          </Rule>
          <Rule
            why={
              <>
                Names are the web's in camel case: <Code>--card-foreground</Code> is <Code>cardForeground</Code> on
                both platforms.
              </>
            }
          >
            Use a role, never a hex value, so a change to Avenue lands in every app at once.
          </Rule>
          <Rule why="The same floor as the web on a phone (AVE-22).">
            Every control is at least {native.touchMinimum} points tall and wide, with{" "}
            {native.spacing.controls} points between two things you can tap.
          </Rule>
        </Rules>
      </Section>

      <Section title="Components on a phone" note="The control each app builds an Avenue component from.">
          <table className="w-full max-w-5xl table-fixed border-collapse text-meta wrap-anywhere">
            <caption className="sr-only">Avenue components and their iOS and Android controls</caption>
            <thead>
              <tr className="border-b text-left text-muted-foreground">
                <th scope="col" className="py-row-y pr-group font-medium">
                  Avenue
                </th>
                <th scope="col" className="py-row-y pr-group font-medium">
                  iOS (SwiftUI)
                </th>
                <th scope="col" className="py-row-y font-medium">
                  Android (Compose)
                </th>
              </tr>
            </thead>
            <tbody>
              {controls.map(([avenue, ios, android]) => (
                <tr key={avenue} className="border-b align-top">
                  <th scope="row" className="py-row-y pr-group text-left font-medium">
                    {avenue}
                  </th>
                  <td className="py-row-y pr-group">{ios}</td>
                  <td className="py-row-y">{android}</td>
                </tr>
              ))}
            </tbody>
          </table>
      </Section>

      <Section title="Colour roles" note="sRGB, as the apps receive them. The tints colour avatars and street bars.">
          <table className="w-full max-w-4xl table-fixed border-collapse text-meta wrap-anywhere">
            <caption className="sr-only">Colour roles in light and dark</caption>
            <thead>
              <tr className="border-b text-left text-muted-foreground">
                <th scope="col" className="py-row-y pr-group font-medium">
                  Role
                </th>
                <th scope="col" className="py-row-y pr-group font-medium">
                  Light
                </th>
                <th scope="col" className="py-row-y font-medium">
                  Dark
                </th>
              </tr>
            </thead>
            <tbody>
              {roles.map((role) => (
                <tr key={role} className="border-b">
                  <th scope="row" className="py-row-y pr-group text-left font-normal">
                    <Code className="text-foreground">{camel(role)}</Code>
                  </th>
                  <td className="py-row-y pr-group">
                    <Swatch hex={native.light[role]} />
                  </td>
                  <td className="py-row-y">
                    <Swatch hex={native.dark[role]} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
      </Section>

      <Section title="Type, corners and spacing" note="Points on iOS; dp on Android, sp for text.">
        <div className="grid max-w-4xl gap-section md:grid-cols-3">
          <dl className="m-0 grid grid-cols-[auto_1fr] gap-x-group gap-y-inline text-meta">
            {Object.entries(native.text).map(([name, step]) => (
              <div key={name} className="contents">
                <dt>
                  <Code className="text-foreground">{name}</Code>
                </dt>
                <dd className="m-0 tabular-nums">
                  {step.size} / {step.lineHeight}
                </dd>
              </div>
            ))}
          </dl>
          <dl className="m-0 grid grid-cols-[auto_1fr] gap-x-group gap-y-inline text-meta">
            {Object.entries(native.radius).map(([name, value]) => (
              <div key={name} className="contents">
                <dt>
                  <Code className="text-foreground">radius.{name}</Code>
                </dt>
                <dd className="m-0 tabular-nums">{value}</dd>
              </div>
            ))}
          </dl>
          <dl className="m-0 grid grid-cols-[auto_1fr] gap-x-group gap-y-inline text-meta">
            {Object.entries(native.spacing).map(([name, value]) => (
              <div key={name} className="contents">
                <dt>
                  <Code className="text-foreground">{camel(name)}</Code>
                </dt>
                <dd className="m-0 tabular-nums">{value}</dd>
              </div>
            ))}
          </dl>
        </div>
      </Section>
    </Page>
  );
}

const meta = {
  title: "Foundations/Native",
  parameters: { layout: "fullscreen" },
} satisfies Meta;

export default meta;

export const Use: StoryObj<typeof meta> = { name: "Native apps", render: () => <NativeUse /> };
